def upload_collection_configs(self, collection, fs_path):
        """
        Uploads collection configurations from a specified directory to zookeeper. 

        """
        if not os.path.exists(fs_path):
            raise Exception("Path %s does not exist" % fs_path)

        if not os.path.isdir(fs_path):
            raise Exception("Path %s is not a directory" % fs_path)

        if not os.path.isabs(fs_path):
            raise Exception("Path %s is not absolute" % fs_path)

        if not collection:
            raise Exception("Collection name is required")

        if not self.is_collection_exists(collection):
            raise Exception("Collection %s does not exist" % collection)

        if not self.is_collection_loaded(collection):
            raise Exception("Collection %s is not loaded" % collection)

        if not self.is_collection_active(collection):
            raise Exception("Collection %s is not active" % collection)

        if not self.is_collection_config_loaded(collection):
            raise Exception("Collection %s config is not loaded" % collection)

        if not self.is_collection_config_active(collection):
            raise Exception("Collection %s config is not active" % collection)

        self.log.info("Uploading collection configs from %s to zookeeper" % fs_path)
        self.zk.upload_collection_configs(collection, fs_path)
        self.log.info("Done uploading collection configs from %s to zookeeper" % fs_path)

